namespace RecipeShare.Services;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public string Ingredients { get; set; } = "";
    public string Steps { get; set; } = "";
    public List<int> Ratings { get; set; } = [];

    public double AverageRating => Ratings.Count > 0
        ? Math.Round(Ratings.Average(), 1)
        : 0;
}

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
            Ingredients = "2 cups flour\n2 eggs\n1½ cups milk\n2 tbsp sugar\n1 tsp baking powder\nPinch of salt",
            Steps = "1. Mix dry ingredients.\n2. Whisk eggs and milk, combine with dry mix.\n3. Cook on a buttered griddle until golden on both sides.",
            Ratings = [4, 5, 4]
        },
        new()
        {
            Id = 2, Title = "Avocado Toast", Category = "Breakfast",
            Ingredients = "2 slices sourdough bread\n1 ripe avocado\nSalt and pepper\nRed pepper flakes\nLemon juice",
            Steps = "1. Toast the bread until crispy.\n2. Mash avocado with salt, pepper, and lemon juice.\n3. Spread on toast and top with red pepper flakes.",
            Ratings = [5, 5]
        },
        new()
        {
            Id = 3, Title = "Spaghetti Carbonara", Category = "Dinner",
            Ingredients = "400g spaghetti\n200g pancetta\n4 egg yolks\n1 cup Pecorino Romano\nBlack pepper",
            Steps = "1. Cook spaghetti al dente.\n2. Fry pancetta until crispy.\n3. Toss hot pasta with pancetta, then quickly stir in yolks and cheese off heat.\n4. Season with black pepper.",
            Ratings = [5, 4, 5, 5]
        },
        new()
        {
            Id = 4, Title = "Chicken Stir-Fry", Category = "Dinner",
            Ingredients = "500g chicken breast\n2 bell peppers\n1 cup broccoli\n3 tbsp soy sauce\n1 tbsp sesame oil\nGarlic and ginger",
            Steps = "1. Slice chicken and vegetables.\n2. Stir-fry chicken in sesame oil until cooked.\n3. Add vegetables and garlic/ginger, cook 3 minutes.\n4. Add soy sauce and serve over rice.",
            Ratings = [4, 3, 4]
        },
        new()
        {
            Id = 5, Title = "Chocolate Brownies", Category = "Desserts",
            Ingredients = "200g dark chocolate\n150g butter\n3 eggs\n1 cup sugar\n¾ cup flour\n1 tsp vanilla",
            Steps = "1. Melt chocolate and butter together.\n2. Beat eggs and sugar, fold in chocolate mixture.\n3. Add flour and vanilla.\n4. Bake at 350°F for 25 minutes.",
            Ratings = [5, 5, 5, 4]
        },
        new()
        {
            Id = 6, Title = "Lemon Tart", Category = "Desserts",
            Ingredients = "1 shortcrust pastry shell\n4 lemons (juice and zest)\n4 eggs\n1 cup sugar\n½ cup cream",
            Steps = "1. Blind-bake pastry shell at 375°F for 15 minutes.\n2. Whisk lemon juice, zest, eggs, sugar, and cream.\n3. Pour into shell and bake at 325°F for 30 minutes.\n4. Cool before serving.",
            Ratings = [4, 5]
        },
        new()
        {
            Id = 7, Title = "Caesar Salad", Category = "Lunch",
            Ingredients = "1 head romaine lettuce\nCroutons\nParmesan cheese\nCaesar dressing\nGrilled chicken (optional)",
            Steps = "1. Chop romaine and place in a large bowl.\n2. Add croutons and shaved Parmesan.\n3. Toss with Caesar dressing.\n4. Top with grilled chicken if desired.",
            Ratings = [3, 4, 4]
        },
        new()
        {
            Id = 8, Title = "Tomato Soup", Category = "Lunch",
            Ingredients = "6 ripe tomatoes\n1 onion\n2 cloves garlic\n2 cups vegetable broth\nBasil\nOlive oil",
            Steps = "1. Roast tomatoes, onion, and garlic with olive oil at 400°F for 30 minutes.\n2. Blend with broth until smooth.\n3. Simmer 10 minutes, season to taste.\n4. Garnish with fresh basil.",
            Ratings = [5, 4]
        }
    ];

    private int _nextId = 9;

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().Order().ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
            recipe.Ratings.Add(stars);
    }

    public void AddRecipe(string title, string category, string ingredients, string steps)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps
        });
    }
}

