﻿@page "/"
@using RecipeShare.Services
@inject RecipeService Recipes

<PageTitle>RecipeShare — Home</PageTitle>

<div class="text-center mb-4">
    <h1>🍳 RecipeShare</h1>
    <p class="lead">Discover and share delicious recipes with the community.</p>
</div>

<h2>Browse by Category</h2>
<div class="row row-cols-1 row-cols-md-2 row-cols-lg-4 g-4">
    @foreach (var category in Recipes.GetCategories())
    {
        <div class="col">
            <a href="category/@category" class="text-decoration-none">
                <div class="card h-100 text-center shadow-sm">
                    <div class="card-body">
                        <h3 class="card-title">@CategoryIcon(category) @category</h3>
                        <p class="card-text text-muted">
                            @Recipes.GetByCategory(category).Count recipe(s)
                        </p>
                    </div>
                </div>
            </a>
        </div>
    }
</div>

<div class="mt-4 text-center">
    <a href="submit" class="btn btn-success btn-lg">📝 Submit a Recipe</a>
</div>

@code {
    private static string CategoryIcon(string category) => category switch
    {
        "Breakfast" => "🌅",
        "Lunch" => "🥗",
        "Dinner" => "🍝",
        "Desserts" => "🍰",
        _ => "🍽️"
    };
}

