@page "/category/{CategoryName}"
@using RecipeShare.Services
@inject RecipeService Recipes

<PageTitle>@CategoryName Recipes — RecipeShare</PageTitle>

<h1>@CategoryName Recipes</h1>

@if (recipes.Count == 0)
{
    <p class="text-muted">No recipes found in this category.</p>
}
else
{
    <div class="row row-cols-1 row-cols-md-2 g-4">
        @foreach (var recipe in recipes)
        {
            <div class="col">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h4 class="card-title">@recipe.Title</h4>
                        <p class="card-text">
                            @if (recipe.AverageRating > 0)
                            {
                                <span>@RenderStars(recipe.AverageRating) (@recipe.Ratings.Count ratings)</span>
                            }
                            else
                            {
                                <span class="text-muted">No ratings yet</span>
                            }
                        </p>
                        <a href="recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<div class="mt-3">
    <a href="/" class="btn btn-link">← Back to categories</a>
</div>

@code {
    [Parameter] public string CategoryName { get; set; } = "";

    private IReadOnlyList<Recipe> recipes = [];

    protected override void OnParametersSet()
    {
        recipes = Recipes.GetByCategory(CategoryName);
    }

    private static string RenderStars(double rating)
    {
        int full = (int)Math.Round(rating);
        return new string('★', full) + new string('☆', 5 - full);
    }
}

@page "/recipe/{Id:int}"
@using RecipeShare.Services
@inject RecipeService Recipes

@if (recipe is null)
{
    <PageTitle>Not Found — RecipeShare</PageTitle>
    <h1>Recipe not found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
}
else
{
    <PageTitle>@recipe.Title — RecipeShare</PageTitle>

    <h1>@recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@recipe.Category</span>

    <div class="row mt-3">
        <div class="col-md-5">
            <div class="card">
                <div class="card-header"><strong>Ingredients</strong></div>
                <div class="card-body">
                    <ul class="mb-0">
                        @foreach (var line in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                        {
                            <li>@line</li>
                        }
                    </ul>
                </div>
            </div>
        </div>
        <div class="col-md-7">
            <div class="card">
                <div class="card-header"><strong>Steps</strong></div>
                <div class="card-body">
                    @foreach (var line in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <p class="mb-1">@line</p>
                    }
                </div>
            </div>
        </div>
    </div>

    <div class="mt-4">
        <h4>Rate this recipe</h4>
        <StarRating RecipeId="recipe.Id" @rendermode="InteractiveServer" />
    </div>
}

<div class="mt-3">
    @if (recipe is not null)
    {
        <a href="category/@recipe.Category" class="btn btn-link">← Back to @recipe.Category</a>
    }
    else
    {
        <a href="/" class="btn btn-link">← Back to home</a>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = Recipes.GetById(Id);
    }
}

@using RecipeShare.Services
@inject RecipeService Recipes

<div>
    @for (int i = 1; i <= 5; i++)
    {
        int star = i;
        <span role="button"
              style="font-size:1.8rem; cursor:pointer; color:@(star <= (hovered ?? selected) ? "gold" : "#ccc")"
              @onclick="() => Rate(star)"
              @onmouseover="() => hovered = star"
              @onmouseout="() => hovered = null">
            ★
        </span>
    }

    @if (submitted)
    {
        <span class="ms-2 text-success">Thanks for rating!</span>
    }

    @if (currentAverage > 0)
    {
        <div class="text-muted small mt-1">
            Average: @currentAverage / 5 (@totalRatings ratings)
        </div>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private int selected;
    private int? hovered;
    private bool submitted;
    private double currentAverage;
    private int totalRatings;

    protected override void OnParametersSet()
    {
        RefreshStats();
    }

    private void Rate(int stars)
    {
        selected = stars;
        Recipes.AddRating(RecipeId, stars);
        submitted = true;
        RefreshStats();
    }

    private void RefreshStats()
    {
        var recipe = Recipes.GetById(RecipeId);
        if (recipe is not null)
        {
            currentAverage = recipe.AverageRating;
            totalRatings = recipe.Ratings.Count;
        }
    }
}

@page "/submit"
@rendermode InteractiveServer
@using System.ComponentModel.DataAnnotations
@using RecipeShare.Services
@inject RecipeService Recipes
@inject NavigationManager Nav

<PageTitle>Submit a Recipe — RecipeShare</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p>Share your favorite recipe with the community.</p>

@if (successMessage is not null)
{
    <div class="alert alert-success">@successMessage</div>
}

<EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submit-recipe" class="mb-4">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" @bind-Value="model.Title" class="form-control" placeholder="e.g. Grandma's Apple Pie" />
        <ValidationMessage For="() => model.Title" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" @bind-Value="model.Category" class="form-select">
            <option value="">-- Select a category --</option>
            <option value="Breakfast">Breakfast</option>
            <option value="Lunch">Lunch</option>
            <option value="Dinner">Dinner</option>
            <option value="Desserts">Desserts</option>
        </InputSelect>
        <ValidationMessage For="() => model.Category" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" @bind-Value="model.Ingredients" class="form-control" rows="5"
                       placeholder="2 cups flour&#10;1 cup sugar&#10;..." />
        <ValidationMessage For="() => model.Ingredients" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps</label>
        <InputTextArea id="steps" @bind-Value="model.Steps" class="form-control" rows="5"
                       placeholder="1. Preheat oven to 350°F&#10;2. Mix ingredients..." />
        <ValidationMessage For="() => model.Steps" class="text-danger" />
    </div>

    <button type="submit" class="btn btn-success">Submit Recipe</button>
</EditForm>

@code {
    private RecipeFormModel model = new();
    private string? successMessage;

    private void HandleSubmit()
    {
        Recipes.AddRecipe(model.Title, model.Category, model.Ingredients, model.Steps);
        successMessage = $""{model.Title}" has been submitted!";
        model = new();
    }

    private sealed class RecipeFormModel
    {
        [Required(ErrorMessage = "Please enter a recipe title.")]
        [StringLength(100, MinimumLength = 3)]
        public string Title { get; set; } = "";

        [Required(ErrorMessage = "Please select a category.")]
        public string Category { get; set; } = "";

        [Required(ErrorMessage = "Please list the ingredients.")]
        public string Ingredients { get; set; } = "";

        [Required(ErrorMessage = "Please describe the steps.")]
        public string Steps { get; set; } = "";
    }
}

